\newcommand{\Count}{\operatorname{Count}}
\newcommand{\vtwo}{v_2}
\DeclareMathOperator{\dens}{dens}

\title{Carry Reformulation and Exact Densities for Cusick's Binary Sum-of-Digits Problem}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}
\begin{abstract}
Let $s_2(n)$ denote the binary sum-of-digits function (the number of $1$s in the
binary expansion of $n$). For a fixed shift $t\ge1$, Cusick's conjecture asserts
that the natural density
$c_t=\lim_{N\to\infty}\frac1N\#\{0\le n<N : s_2(n+t)\ge s_2(n)\}$
satisfies $c_t>\tfrac12$, with the explicit bound $c_t\ge\tfrac12+2^{-(2s_2(t)+1)}$.
We give a self-contained development of the structural arithmetic of the problem and
prove several exact results. Our central reformulation expresses the Cusick event
via base-$2$ carries: by Kummer's theorem the carry count is $\vtwo\binom{n+t}{t}$,
and the exact identity $s_2(n+t)+K(n,t)=s_2(n)+s_2(t)$ shows that
$s_2(n)\le s_2(n+t)$ iff $K(n,t)\le s_2(t)$. We establish subadditivity of $s_2$ via
the additive Legendre identity $s_2(n)+\vtwo(n!)=n$; the exact block average
$\sum_{x<2^k}s_2(x)=k\,2^{k-1}$; the exact density $c_1=\tfrac34$ through the
criterion $s_2(n)\le s_2(n+1)\iff n\not\equiv3\ (\mathrm{mod}\ 4)$; a doubling
self-similarity $\Count(2t,2N)=2\,\Count(t,N)$ with orbit form
$\Count(2^kt,2^kN)=2^k\,\Count(t,N)$ proving the density is constant along
$\{t,2t,4t,\dots\}$; and the exact density $c_{2^k}=\tfrac34$ for every power-of-two
shift, with explicit surplus $2^km$ over the fair half. All results are formally
verified.
\end{abstract}

\maketitle

\section{Introduction}
The binary sum-of-digits function $s_2$ pervades automatic sequences, carry
propagation analysis, Hamming-weight circuit complexity, and the combinatorics of
Pascal's triangle modulo $2$. In 1990 Cusick asked whether, for a fixed shift $t$,
the event ``the binary digit sum does not decrease under $n\mapsto n+t$'' is more
common than its complement. He conjectured the affirmative for every $t\ge1$ with a
quantitative floor degrading only with the digit complexity of $t$:
\begin{equation}\label{eq:cusick}
c_t \;\ge\; \tfrac12 + 2^{-(2 s_2(t)+1)}.
\end{equation}
The difficulty is that the unconditional mean of $s_2$ over a dyadic block is
exactly $k/2$ (Theorem~\ref{thm:block}): the baseline is a fair coin, so any bias
arises from the fine carry structure of addition. We develop that structure from
first principles and extract every density it pins down exactly: a carry
reformulation (\S3), and the exact values $c_1=\tfrac34$ (\S4) and $c_{2^k}=\tfrac34$
for all $k$ (\S5), the latter from the former via a doubling self-similarity.
Throughout, $\vtwo(m)$ is the $2$-adic valuation of $m$ and $[a,b)$ is the integer
interval $\{a,\dots,b-1\}$.

\subsection*{Background}
Legendre's formula gives $\vtwo(n!)=(n-s_2(n))/(2-1)$, i.e. $s_2(n)+\vtwo(n!)=n$,
linearizing the digit sum into a valuation statement. Kummer's theorem (1852)
identifies the base-$2$ carry count of $m+n$ with $\vtwo\binom{m+n}{n}$, turning
digit-sum statistics into carry statistics. The natural density of $S\subseteq\mathbb{N}$
is $\dens(S)=\lim_N\#(S\cap[0,N))/N$; here the counting functions are exactly linear
on aligned dyadic blocks, so the densities are exact rationals. Since the mean of
$s_2$ over a block is exactly $k/2$ (Theorem~\ref{thm:block}), a symmetric random
model predicts $c_t=\tfrac12$; Cusick's conjecture asserts the carry structure breaks
this symmetry in a fixed direction for every shift.

\section{The binary digit sum}
\begin{definition}[\texttt{s2}]
For $n\in\mathbb{N}$, $s_2(n):=(\text{digits}_2 n).\mathrm{sum}$, the sum of base-$2$
digits of $n$ (equivalently the popcount). Thus $s_2(0)=0$, $s_2(1)=1$.
\end{definition}

\begin{proposition}[\texttt{s2\_le}]
$s_2(n)\le n$ for all $n$.
\end{proposition}

\begin{theorem}[Legendre, additive form; \texttt{s2\_add\_val}]\label{thm:legendre}
$s_2(n)+\vtwo(n!) = n$ for all $n\in\mathbb{N}$.
\end{theorem}
\begin{proof}[Proof sketch]
The Legendre/de Polignac formula gives $(2-1)\vtwo(n!)=n-s_2(n)$ at the prime $2$;
since $s_2(n)\le n$, rearrange in $\mathbb{N}$.
\end{proof}

\begin{lemma}[\texttt{padicVal2\_mono}]\label{lem:mono}
If $k\ne0$ and $m\mid k$, then $\vtwo(m)\le\vtwo(k)$.
\end{lemma}
\begin{proof}[Proof sketch]
$2^{\vtwo(m)}\mid m\mid k$, so $2^{\vtwo(m)}\mid k$, whence $\vtwo(m)\le\vtwo(k)$.
\end{proof}

\begin{theorem}[Subadditivity; \texttt{s2\_subadditive}]\label{thm:subadd}
$s_2(a+b)\le s_2(a)+s_2(b)$ for all $a,b$, with equality iff adding $a,b$ in base $2$
produces no carries.
\end{theorem}
\begin{proof}[Proof sketch]
Since $\binom{a+b}{a}\in\mathbb{Z}$, $a!\,b!\mid(a+b)!$, so by Lemma~\ref{lem:mono}
and additivity of $\vtwo$ on products, $\vtwo(a!)+\vtwo(b!)\le\vtwo((a+b)!)$.
Substituting Theorem~\ref{thm:legendre} for $a,b,a+b$ and simplifying gives the
claim.
\end{proof}

\begin{theorem}[Block average; \texttt{s2\_block\_sum}]\label{thm:block}
For every $k$, $\sum_{x=0}^{2^k-1}s_2(x)=k\cdot2^{k-1}$, so the mean of $s_2$ over
$[0,2^k)$ is exactly $k/2$.
\end{theorem}
\begin{proof}[Proof sketch]
Each of the $k$ bit-positions is $1$ for exactly half of the $2^k$ numbers,
contributing $2^{k-1}$; sum over positions.
\end{proof}

\section{The carry reformulation}
\begin{definition}[Carry count; \texttt{carries}]
For $t,n\in\mathbb{N}$, $K(n,t):=\vtwo\binom{n+t}{t}$. By Kummer's theorem this is
the number of carries when adding $n$ and $t$ in base $2$.
\end{definition}

\begin{theorem}[Kummer, subtraction form; \texttt{carries\_eq\_sub}]\label{thm:kummer}
$K(n,t)=s_2(t)+s_2(n)-s_2(n+t)$.
\end{theorem}

\begin{corollary}[Exact carry identity; \texttt{s2\_add\_carries}]\label{cor:identity}
$s_2(n+t)+K(n,t)=s_2(n)+s_2(t)$.
\end{corollary}
\begin{proof}[Proof sketch]
Add $s_2(n+t)$ to Theorem~\ref{thm:kummer}; the truncated subtraction is valid
because $s_2(n+t)\le s_2(n)+s_2(t)$ by Theorem~\ref{thm:subadd}.
\end{proof}

\begin{theorem}[Cusick event as carry inequality; \texttt{cusick\_reformulation}]\label{thm:reform}
$s_2(n)\le s_2(n+t)\iff K(n,t)\le s_2(t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Substitute $s_2(n+t)=s_2(n)+s_2(t)-K(n,t)$ from Corollary~\ref{cor:identity} into
$s_2(n)\le s_2(n+t)$ and cancel $s_2(n)$.
\end{proof}

\begin{corollary}[No-carry case; \texttt{cusick\_of\_no\_carry}]
If $K(n,t)=0$ then $s_2(n+t)=s_2(n)+s_2(t)$.
\end{corollary}

\begin{proposition}[Unconditional bound; \texttt{carries\_le\_total}]
$K(n,t)\le s_2(n)+s_2(t)$ for all $n,t$.
\end{proposition}

\section{The exact density for $t=1$}
\begin{lemma}[High-bit additivity; \texttt{s2\_high\_bit}]\label{lem:high}
If $t<2^L$ then $s_2(t+2^L)=s_2(t)+1$.
\end{lemma}

\begin{theorem}[Good set infinite; \texttt{cusick\_good\_set\_infinite}]
For every $t$, $\{n:s_2(n)\le s_2(n+t)\}$ is infinite.
\end{theorem}
\begin{proof}[Proof sketch]
The injective family $n=2^{j+t}$ lies in the set: by Lemma~\ref{lem:high},
$s_2(2^{j+t})=1$ and $s_2(2^{j+t}+t)=s_2(t)+1\ge1$.
\end{proof}

\begin{theorem}[Congruence criterion; \texttt{cusick\_t1\_iff}]\label{thm:t1iff}
$s_2(n)\le s_2(n+1)\iff n\not\equiv3\ (\mathrm{mod}\ 4)$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:reform} with $t=1$ (and $s_2(1)=1$) the event is $K(n,1)\le1$.
Here $K(n,1)=\vtwo\binom{n+1}{1}=\vtwo(n+1)$, so it fails iff $4\mid(n+1)$.
\end{proof}

\begin{lemma}[Residue count; \texttt{count\_mod4\_ne\_three}]\label{lem:count4}
$\#\{n<4m:n\not\equiv3\ (\mathrm{mod}\ 4)\}=3m$.
\end{lemma}

\begin{theorem}[Exact density $c_1=3/4$; \texttt{cusick\_t1\_density}]\label{thm:c1}
$\#\{n<4m:s_2(n)\le s_2(n+1)\}=3m$, hence $c_1=\tfrac34$, clearing the floor
\eqref{eq:cusick} value $\tfrac58$ by $\tfrac18$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:t1iff} the filtered set equals
$\{n<4m:n\not\equiv3\ (\mathrm{mod}\ 4)\}$, of size $3m$ by Lemma~\ref{lem:count4};
divide by $4m$.
\end{proof}

\section{Doubling self-similarity and the power-of-two family}
\begin{lemma}[Bit append; \texttt{s2\_two\_mul}, \texttt{s2\_two\_mul\_add\_one}]\label{lem:append}
$s_2(2n)=s_2(n)$ and $s_2(2n+1)=s_2(n)+1$.
\end{lemma}

\begin{theorem}[Doubling invariance; \texttt{cusick\_double\_even}, \texttt{cusick\_double\_odd}]\label{thm:double}
For all $n,t$,
\[ s_2(2n)\le s_2(2n+2t)\iff s_2(n)\le s_2(n+t), \]
\[ s_2(2n+1)\le s_2(2n+1+2t)\iff s_2(n)\le s_2(n+t). \]
\end{theorem}
\begin{proof}[Proof sketch]
Even: $2n+2t=2(n+t)$, drop the low bit by Lemma~\ref{lem:append}. Odd:
$2n+1+2t=2(n+t)+1$; both sides gain $+1$, which cancels.
\end{proof}

\begin{definition}[Counting function; \texttt{cusickCount}]
$\Count(t,N):=\#\{n<N:s_2(n)\le s_2(n+t)\}$.
\end{definition}

\begin{lemma}[Fibre split; \texttt{card\_filter\_range\_two\_mul}]
$\#\{n<2N:P(n)\}=\#\{j<N:P(2j)\}+\#\{j<N:P(2j+1)\}$.
\end{lemma}

\begin{theorem}[Self-similarity; \texttt{cusickCount\_two\_mul}]\label{thm:selfsim}
$\Count(2t,2N)=2\,\Count(t,N)$.
\end{theorem}
\begin{proof}[Proof sketch]
Split over even/odd fibres; Theorem~\ref{thm:double} identifies each fibre with the
base event, contributing $\Count(t,N)$ apiece.
\end{proof}

\begin{theorem}[Pointwise criterion for $2^k$; \texttt{cusick\_pow2\_iff}]\label{thm:pow2iff}
$s_2(n)\le s_2(n+2^k)\iff\lfloor n/2^k\rfloor\not\equiv3\ (\mathrm{mod}\ 4)$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $n=2^kq+r$, $r<2^k$. By digit concatenation $s_2(2^kx+r)=s_2(x)+s_2(r)$, so
the event reduces to the $t=1$ criterion (Theorem~\ref{thm:t1iff}) at
$q=\lfloor n/2^k\rfloor$.
\end{proof}

\begin{theorem}[Exact density $c_{2^k}=3/4$; \texttt{cusick\_pow2\_density}]\label{thm:pow2dens}
For all $k,m$, $\Count(2^k,2^{k+2}m)=3\cdot2^k\cdot m$, hence $c_{2^k}=\tfrac34$ for
every $k\ge0$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$; base case Theorem~\ref{thm:c1}. For the step,
$2^{(k+1)+2}m=2(2^{k+2}m)$ and Theorem~\ref{thm:selfsim} with the hypothesis give
$\Count(2^{k+1},2^{k+3}m)=2\cdot3\cdot2^km=3\cdot2^{k+1}m$.
\end{proof}

\begin{theorem}[Orbit invariance; \texttt{cusickCount\_two\_pow\_mul}]\label{thm:orbit}
$\Count(2^kt,2^kN)=2^k\,\Count(t,N)$; equivalently $c_{2^kt}=c_t$: the density
depends only on the odd part of $t$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$, each step an instance of Theorem~\ref{thm:selfsim}.
\end{proof}

\begin{theorem}[Explicit bias; \texttt{cusick\_pow2\_bias}]\label{thm:bias}
$\Count(2^k,2^{k+2}m)=2^{k+1}m+2^km$. The fair half of $[0,2^{k+2}m)$ is
$2^{k+1}m$, so the good count exceeds it by exactly $2^km=\tfrac14\cdot2^{k+2}m$,
giving $c_{2^k}-\tfrac12=\tfrac14$.
\end{theorem}

\section{Worked examples and numerical evidence}
We illustrate the machinery on concrete values; all are reproducible by direct
enumeration.

\emph{Carry identity.} For $n=55=110111_2$ ($s_2=5$), $t=1$: $n+t=56=111000_2$
($s_2=3$), and the trailing run $111_2$ yields $K(55,1)=3$. Then
$s_2(n+t)+K=3+3=6=s_2(n)+s_2(t)$ (Corollary~\ref{cor:identity}), and
$\binom{56}{1}=2^3\cdot7$ gives $\vtwo\binom{56}{1}=3$. Since $K=3>s_2(t)=1$ the
event fails, matching $55\equiv3\ (\mathrm{mod}\ 4)$ (Theorem~\ref{thm:t1iff}).

\emph{No-carry good start.} For $n=8=1000_2$, $t=1$: $n+t=9=1001_2$, $K=0$, so
$s_2(n+t)=s_2(n)+s_2(t)=2$ and the event holds.

\emph{Exact $c_1$.} Over $[0,12)$ the failures are $3,7,11$ (those $\equiv3\ \mathrm{mod}\ 4$),
so $9$ of $12$ succeed: $3m=9$ at $m=3$ (Theorem~\ref{thm:c1}), density $3/4$.

\emph{Doubling.} $\Count(1,4)=3\Rightarrow\Count(2,8)=6$ (Theorem~\ref{thm:selfsim}),
and over $[0,8)$ the successes for $t=2$ are $0,1,2,3,4,6$.

Direct enumeration over $N=2^{16}$ gives the densities below, with the floor
\eqref{eq:cusick}:
\[
\begin{array}{c|c|c|c|c|c}
t & \text{binary} & s_2(t) & c_t & \text{floor} & \text{status}\\\hline
1 & 1   & 1 & 3/4   & 5/8   & \text{proven (Thm \ref{thm:c1})}\\
2 & 10  & 1 & 3/4   & 5/8   & \text{proven (Thm \ref{thm:pow2dens})}\\
3 & 11  & 2 & 11/16 & 17/32 & \text{empirical}\\
4 & 100 & 1 & 3/4   & 5/8   & \text{proven (Thm \ref{thm:pow2dens})}\\
5 & 101 & 2 & 5/8   & 17/32 & \text{empirical}\\
7 & 111 & 3 & 43/64 & 65/128& \text{empirical}
\end{array}
\]
Note $c_3=11/16$ and $c_5=5/8$ share $s_2(t)=2$ yet differ: the bias depends on the
bit \emph{pattern}, not only the count (cf.\ Conjecture C4).

\section{Algorithms}
\textbf{Algorithm A (carry-based predicate).} To decide $s_2(n)\le s_2(n+t)$, test
$K(n,t)\le s_2(t)$ (Theorem~\ref{thm:reform}); $K(n,t)$ is the number of base-$2$
carries in $n+t$, computable by a single $O(\log(n+t))$ bit scan, or as
$\vtwo\binom{n+t}{t}$.

\textbf{Algorithm B (doubling recursion).} For $\Count(t,N)$ with $t,N$ even,
recurse by Theorem~\ref{thm:selfsim}. Stripping $2^{\vtwo(t)}$ reduces to the
odd-shift base case; for power-of-two shifts Theorem~\ref{thm:pow2dens} gives the
closed form in $O(1)$.

\section{Applications}
(i) Circuit complexity: $s_2$ is Hamming weight and $K(n,t)$ counts full-adder
activations in $n+t$. (ii) Automatic sequences: $s_2\bmod2$ is Thue--Morse, and the
digit-concatenation identity of Theorem~\ref{thm:pow2iff} is its substitutive
self-similarity. (iii) Probabilistic carry models: Theorem~\ref{thm:block} (mean
$k/2$) with Theorem~\ref{thm:reform} formalizes the stopped-random-walk heuristic
biased toward few carries.

\section{Discussion and future directions}
The results pin down $c_t$ exactly on all shifts with odd part $1$ (the powers of
two), giving $c_{2^k}=\tfrac34$, and reduce every shift's density to that of its odd
part. The carry reformulation (Theorem~\ref{thm:reform}) is unconditional; the exact
densities exploit that for $t=2^k$ the carry count is governed by a single digit
transition (Theorem~\ref{thm:pow2iff}), as for $t=1$. For general $t$ with
$s_2(t)\ge2$, adding $t$ triggers several carry chains, and the right object is the
distribution of $K(n,t)$ over a period --- a stopped-random-walk law whose first-exit
behaviour is exactly Cusick's bound. The table of \S6 shows that shifts with equal
$s_2(t)$ (e.g. $t=3,5$) can have different densities, so an exact formula must see the
full digit pattern. The doubling theory reduces everything to odd shifts
($c_{2^kt}=c_t$, Theorem~\ref{thm:orbit}); the Mersenne blocks $t=2^j-1$ (C2) are the
natural next target. We list testable conjectures.

\textbf{C1.} The predicate $P_t(n)=[s_2(n)\le s_2(n+t)]$ is purely periodic with
minimal period $2^{(\text{length }t)+s_2(t)}$; minimality needs one explicit
distinguishing residue.

\textbf{C2.} With periodicity, $A(t):=\Count(t,2^{L+s_2(t)})$ is an integer;
$A(2^k-1)=3,11,43,171,683$ fit $A(2^k-1)=(2\cdot4^k+1)/3$ via the recurrence
$A_{k+1}=4A_k-1$.

\textbf{C3.} A strengthened bias $c_t-\tfrac12\ge2^{-2s_2(t)}$, from the one-digit
deterministic deficit in the overflow regime.

\textbf{C4.} Finer dependence of the density on the digit pattern of the odd part of
$t$, beyond the orbit invariance of Theorem~\ref{thm:orbit}.

