"""Exact Cusick density c_{2^k} = 3/4 for power-of-two shifts.

Exercises the main theorem cusick_pow2_density:
    Count(2^k, 2^(k+2) m) = 3 * 2^k * m
by direct enumeration, and the explicit-bias theorem cusick_pow2_bias.
"""
from __future__ import annotations


def s2(n: int) -> int:
    return bin(n).count("1")


def cusick_count(t: int, N: int) -> int:
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))


def main() -> None:
    for k in range(7):
        for m in range(1, 5):
            N = 2 ** (k + 2) * m
            cnt = cusick_count(2 ** k, N)
            assert cnt == 3 * 2 ** k * m                 # cusick_pow2_density
            assert cnt - 2 ** (k + 1) * m == 2 ** k * m  # cusick_pow2_bias
        print(f"k={k}: c_(2^{k}) = {cnt/N:.4f} = 3/4, "
              f"surplus over half = {cnt - 2**(k+1)*m} = 2^{k}*m")


if __name__ == "__main__":
    main()

"""Carry reformulation of the Cusick event.

Exercises cusick_reformulation:
    s2(n) <= s2(n+t)  <=>  carries(t,n) <= s2(t),
where carries(t,n) = v2(C(n+t, t)) (Kummer), together with the exact carry
identity s2(n+t) + carries = s2(n) + s2(t) (s2_add_carries).
"""
from __future__ import annotations
from math import comb


def s2(n: int) -> int:
    return bin(n).count("1")


def v2(m: int) -> int:
    e = 0
    while m and m % 2 == 0:
        m //= 2
        e += 1
    return e


def carries(t: int, n: int) -> int:
    return v2(comb(n + t, t))


def main() -> None:
    bound = 96
    for t in range(1, bound):
        for n in range(bound):
            K = carries(t, n)
            assert s2(n + t) + K == s2(n) + s2(t)            # s2_add_carries
            assert (s2(n) <= s2(n + t)) == (K <= s2(t))      # cusick_reformulation
    print(f"Carry reformulation verified for all 1<=t<{bound}, n<{bound}.")


if __name__ == "__main__":
    main()

"""Doubling orbit invariance of the Cusick density.

Exercises cusickCount_two_pow_mul:
    Count(2^k t, 2^k N) = 2^k * Count(t, N),
hence the density c_t depends only on the odd part of t. Confirms numerically
that c_1 = 3/4, c_3 = 11/16, c_5 = 5/8 are constant along their doubling orbits.
"""
from __future__ import annotations


def s2(n: int) -> int:
    return bin(n).count("1")


def cusick_count(t: int, N: int) -> int:
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))


def main() -> None:
    window = 1 << 12
    for t in (1, 3, 5, 7):
        ds = []
        for k in range(4):
            assert (cusick_count(2 ** k * t, 2 ** k * window)
                    == 2 ** k * cusick_count(t, window))  # cusickCount_two_pow_mul
            ds.append(cusick_count(2 ** k * t, 2 ** k * window) / (2 ** k * window))
        print(f"odd part t={t}: density along orbit = "
              + ", ".join(f"{d:.4f}" for d in ds))


if __name__ == "__main__":
    main()

